let source = "";
for await (const chunk of process.stdin) source += chunk;
const input = JSON.parse(source || "{}");

const id = input.documentId;
const title = input.title;
const timestamp = input.timestamp;
const key = input.idempotencyKey;
const headers = { "content-type": "application/json" };

const out = {
  http: null,
  database: { rows: [], transaction: { committed: false, rolledBack: false } },
  messages: [],
  outbound: [],
  ordering: [],
  failures: [],
  retryability: false
};

function step(name) {
  out.ordering.push(name);
}

function fail(status, code, retryable, vendorStatus) {
  out.http = { status, headers, body: { error: code } };
  out.failures.push({ stage: code.split(".")[0], code, vendorStatus, retryable });
  out.retryability = retryable;
  out.database.transaction = { committed: false, rolledBack: false };
}

function mapVendor(s) {
  if (s === 401 || s === 403) return [502, "vendor.unauthorized", false];
  if (s === 429) return [503, "vendor.rate_limited", true];
  if (s === 408 || s === 504) return [504, "vendor.timeout", true];
  if (s >= 500) return [502, "vendor.unavailable", true];
  return [502, "vendor.rejected", false];
}

const doc = { id, title, createdAt: timestamp };
const priorKey = input.replayOf ?? input.previousIdempotencyKey;
const isReplay = input.replay === true || (key !== undefined && priorKey === key);

if (input.operation !== undefined && input.operation !== "create") {
  fail(400, "request.unsupported_operation", false);
} else if (typeof title !== "string" || title.trim() === "" || !id) {
  fail(400, "request.invalid", false);
} else if (isReplay) {
  // Idempotent replay: return original result, no vendor calls, writes or events.
  out.http = { status: 200, headers: { ...headers, "idempotent-replay": "true" }, body: doc };
  out.database.rows = [doc];
  out.database.transaction = { committed: false, rolledBack: false, replayed: true };
  step("idempotency.lookup");
} else {
  step("idempotency.lookup");
  const stages = [
    ["authorize", input.vendorStatus ?? 200],
    ["index", input.indexStatus ?? input.vendorStatus ?? 200]
  ];
  let failed = false;
  for (const [name, status] of stages) {
    out.outbound.push({ vendor: "documents", operation: name, documentId: id, timestamp, status });
    step(`vendor.${name}`);
    if (status < 200 || status >= 300) {
      const [h, code, retry] = mapVendor(status);
      fail(h, code, retry, status);
      failed = true;
      break;
    }
  }
  if (!failed) {
    out.database.rows = [{ ...doc, idempotencyKey: key }];
    out.database.transaction = { committed: true, rolledBack: false };
    step("database.commit");
    out.messages.push({ type: "document.created", documentId: id, title, timestamp });
    step("event.emit");
    out.http = { status: 201, headers, body: { id, title, createdAt: timestamp } };
  }
}

console.log(JSON.stringify(out));

